def print_numbers(n):
    for i in range(n):
        for j in range(n):
            print(j)

def print_numbers(n):
    i = 0
    j = 0 
    while i < n:
        print(i)
        i = i + 1

    while j < n:
        print(j)
        j = j + 1

def print_numbers(n):
    for i in range(n):
        if i < n:
            print(n)

